/**
 * Test Case: Valid Login
 *
 * Tags: @master @sanity @regression @web
 *
 * Steps:
 * 1) Navigate to My Account -> Login and verify the login page
 * 2) Log in with valid credentials from the fixed test data
 * 3) Verify the user lands on the authenticated My Account page
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '../../fixtures/pageFixtures';
import { Helper } from '../../utils/helper';

test('Valid user login test @master @sanity @regression @web', async ({ homePage, loginPage, myAccountPage }) => {
    const { email, password } = Helper.getLoginDetails();

    await test.step('1) Navigate to the login page', async () => {
        await homePage.clickMyAccount();
        await homePage.clickLogin();
        expect(await loginPage.isLoginPageExists()).toBeTruthy();
    });

    await test.step('2) Log in with valid credentials', async () => {
        await loginPage.login(email, password);
    });

    await test.step('3) Verify the My Account dashboard is displayed', async () => {
        expect(await myAccountPage.isMyAccountPageExists()).toBeTruthy();
        expect(await myAccountPage.isLogoutLinkExists()).toBeTruthy();
    });

    console.log('✅ ✔️ Valid login completed successfully!');
});
